/**
 * Represents the entire Nuvsha file (component)
 */
export class ComponentNode {
  constructor() {
    this.type = 'Component';
    this.script = ''; // Holds all JavaScript code from <script> blocks
    this.template = []; // Array to hold multiple root HTML elements
  }
}

/**
 * Represents an HTML element like <div> or <h1>
 */
export class ElementNode {
  constructor(tagName, attributes = {}) {
    this.type = 'Element';
    this.tagName = tagName;
    this.attributes = attributes;
    this.children = [];
  }
}

/**
 * Represents pure text inside an element, like "Hello"
 */
export class TextNode {
  constructor(value) {
    this.type = 'Text';
    this.value = value;
  }
}

/**
 * Represents a dynamic JavaScript variable inside the HTML, like {name}
 */
export class ExpressionNode {
  constructor(expression) {
    this.type = 'Expression';
    this.expression = expression;
  }
}

/**
 * Represents an if/else conditional block
 */
export class ConditionalNode {
  constructor(condition) {
    this.type = 'Conditional';
    this.condition = condition;
    this.branches = [
      { condition, children: [] }
    ];
    this.consequent = this.branches[0].children; // Children when true (backward compatibility)
    this.alternate = [];                         // Children when false (backward compatibility)
    this.inElse = false;                         // Parser state flag
  }
}

/**
 * Represents a loop block
 */
export class ForNode {
  constructor(expression) {
    this.type = 'For';
    this.expression = expression; // e.g., "item of items"
    this.children = [];
  }
}

/**
 * Represents a call to an imported user-defined component.
 * Uppercase tag names like <Card /> or <Button label="Go" /> become this node.
 *
 * The component must be imported in the <script> block, e.g.:
 *   import Card from "./components/Card.nuv"
 *
 * The compiler emits: const el3 = Card({ title: "Hello" });
 */
export class ComponentCallNode {
  constructor(name, props = {}) {
    this.type = 'ComponentCall';
    this.name = name;   // The identifier, e.g. "Card", "Button"
    this.props = props; // Same shape as ElementNode.attributes
    this.children = []; // Slotted content (if any)
  }
}

/**
 * Represents a <slot /> inside a child component.
 * When the parent passes children inside <Card>...</Card>,
 * those children render where <slot /> appears in the child template.
 */
export class SlotNode {
  constructor() {
    this.type = 'Slot';
  }
}

/**
 * Represents an {async expr} ... {loading} ... {error} ... {/async} block.
 *
 * Structure:
 *   {async varName = asyncExpression}
 *     children  — shown on success, varName is available
 *   {loading}
 *     loading   — shown while loading
 *   {error}
 *     error     — shown on failure, `error` is available
 *   {/async}
 */
export class AsyncNode {
  constructor(varName, expression) {
    this.type = 'Async';
    this.varName = varName;     // e.g. "user"
    this.expression = expression; // e.g. "getUser()"
    this.children = [];         // success children
    this.loading = [];          // loading children
    this.error = [];            // error children
    this.section = 'success';   // parser state: 'success' | 'loading' | 'error'
  }
}
